import { useMemo, useState } from "react";
import { ActivityIndicator, StyleSheet, View } from "react-native";
import { WebView, type WebViewMessageEvent } from "react-native-webview";

/**
 * Shows a GLB file (e.g. a model generated by AI from a photo) with Google's
 * open-source <model-viewer>, which handles textures, lighting and touch
 * rotation reliably inside a WebView.
 */

function viewerHtml(src: string): string {
  // src comes from our API; JSON.stringify escapes it for the inline script.
  return `<!doctype html><html><head>
<meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1">
<script type="module" src="https://cdn.jsdelivr.net/npm/@google/model-viewer@3.5.0/dist/model-viewer.min.js"></script>
<style>html,body{margin:0;height:100%;background:transparent;overflow:hidden}model-viewer{width:100%;height:100%;--poster-color:transparent}</style>
</head><body>
<model-viewer id="m" camera-controls auto-rotate auto-rotate-delay="0" rotation-per-second="20deg"
  shadow-intensity="1" exposure="1.05" camera-orbit="-35deg 75deg auto" interaction-prompt="none"></model-viewer>
<script>
  var post = function (m) { window.ReactNativeWebView && window.ReactNativeWebView.postMessage(m); };
  var m = document.getElementById("m");
  m.addEventListener("load", function () { post("ready"); });
  m.addEventListener("error", function () { post("error"); });
  m.src = ${JSON.stringify(src)};
</script></body></html>`;
}

export function GlbViewer({ url, height, onError }: { url: string; height: number; onError: () => void }) {
  const [loading, setLoading] = useState(true);
  const html = useMemo(() => viewerHtml(url), [url]);
  // Same origin as the model file, so the viewer may fetch it.
  const origin = useMemo(() => new URL(url).origin, [url]);

  function onMessage(e: WebViewMessageEvent) {
    if (e.nativeEvent.data === "ready") setLoading(false);
    if (e.nativeEvent.data === "error") onError();
  }

  return (
    <View style={[styles.container, { height }]}>
      <WebView
        source={{ html, baseUrl: `${origin}/` }}
        originWhitelist={["http://*", "https://*"]}
        onMessage={onMessage}
        onError={onError}
        javaScriptEnabled
        cacheEnabled
        cacheMode="LOAD_CACHE_ELSE_NETWORK"
        setSupportMultipleWindows={false}
        style={styles.webview}
        // Only our page, the model file and the viewer library may load.
        onShouldStartLoadWithRequest={(req) =>
          req.url === "about:blank" || req.url.startsWith(origin) || req.url.startsWith("https://cdn.jsdelivr.net/")
        }
      />
      {loading && <ActivityIndicator style={StyleSheet.absoluteFill} />}
    </View>
  );
}

const styles = StyleSheet.create({
  container: { width: "100%", borderRadius: 16, overflow: "hidden" },
  webview: { flex: 1, backgroundColor: "transparent" },
});
